/* App parts: sidebar, breadcrumbs, avatars, stat card, charts, data table,
   command menu, drawer, toasts, empty state, skeleton, date range, stepper.
   Colours come from the shared tokens, so themes and dark mode apply. */
:root, .gch, .gdn, .gsp, .gst {
  --gch-0: var(--glass-tint);
  --gch-1: color-mix(in srgb, var(--glass-tint) 45%, #a7adba);
  --gch-2: color-mix(in srgb, var(--glass-tint) 25%, #d6dae2);
  --gch-3: color-mix(in srgb, var(--glass-tint) 70%, #000);
  --gch-good: #17a065;
  --gch-bad: #d12c3a;
}
:is([data-glass-mode="dark"], .dark), :is([data-glass-mode="dark"], .dark) :is(.gch, .gdn, .gsp, .gst) { --gch-2: color-mix(in srgb, var(--glass-tint) 30%, #4a4d57); --gch-3: color-mix(in srgb, var(--glass-tint) 55%, #fff); --gch-good: #4fd08f; --gch-bad: #ff7a84; }
[data-glass-tint="frost"], [data-glass-tint="frost"] :is(.gch, .gdn, .gsp, .gst) { --gch-0: #6f7a8c; --gch-1: #a9b2c1; --gch-2: #d3d9e2; --gch-3: #3f4757; }

/* ---------- Avatar ---------- */
/* Avatar: a soft tone of one hue with the initials in a deeper shade of it */
.gav { --s: 36px; position: relative; display: inline-grid; place-items: center; flex: none; width: var(--s); height: var(--s); border-radius: 50%; font-size: calc(var(--s) * 0.36); font-weight: 600; letter-spacing: -0.02em; line-height: 1;
  color: hsl(var(--h, 220) 48% 30%); background: radial-gradient(120% 100% at 30% 15%, hsl(var(--h, 220) 85% 96%), hsl(var(--h, 220) 70% 86%));
  box-shadow: inset 0 0 0 1px hsl(var(--h, 220) 50% 40% / 0.12), 0 0 0 2.5px var(--gav-ring, #fff); }
.gav[data-size="sm"] { --s: 28px; }
.gav[data-size="lg"] { --s: 48px; }
.gav img { width: 100%; height: 100%; border-radius: 50%; object-fit: cover; }
.gav-dot { position: absolute; right: 0; bottom: 0; width: max(8px, 26%); height: max(8px, 26%); border-radius: 50%; background: #1fa463; box-shadow: 0 0 0 2px var(--gav-ring, #fff); }
.gav-dot[data-status="away"] { background: #f0a020; }
.gav-dot[data-status="busy"] { background: #e5484d; }
.gav-more { color: rgb(var(--glass-shadow) / 0.7); background: rgb(var(--glass-shadow) / 0.07); box-shadow: inset 0 0 0 1px rgb(var(--glass-shadow) / 0.08), 0 0 0 2.5px var(--gav-ring, #fff); font-size: calc(var(--s) * 0.32); }
.gavg { display: inline-flex; }
.gavg .gav { transition: transform 0.35s cubic-bezier(0.3, 1.5, 0.5, 1), margin 0.35s cubic-bezier(0.3, 1.5, 0.5, 1); }
.gavg .gav + .gav { margin-left: calc(var(--s) * -0.16); }
.gavg:hover .gav + .gav { margin-left: calc(var(--s) * 0.06); }
.gavg .gav:hover { transform: translateY(-3px); z-index: 1; }
:is([data-glass-mode="dark"], .dark) .gav { --gav-ring: #1c1c20; color: hsl(var(--h, 220) 85% 82%); background: radial-gradient(120% 100% at 30% 15%, hsl(var(--h, 220) 60% 62% / 0.22), hsl(var(--h, 220) 60% 50% / 0.1)), #26262b; box-shadow: inset 0 0 0 1px hsl(var(--h, 220) 70% 72% / 0.2), 0 0 0 2.5px var(--gav-ring, #1c1c20); }
:is([data-glass-mode="dark"], .dark) .gav-more { color: rgb(255 255 255 / 0.7); background: rgb(255 255 255 / 0.08); }

/* ---------- Breadcrumbs ---------- */
.gbc ol { display: flex; flex-wrap: wrap; align-items: center; gap: 4px; margin: 0; padding: 0; list-style: none; font-size: 13.5px; }
.gbc li { display: inline-flex; align-items: center; gap: 4px; }
.gbc a { color: rgb(var(--glass-shadow) / 0.6); text-decoration: none; border-radius: 6px; padding: 2px 4px; }
.gbc a:hover { color: var(--glass-fg); background: rgb(var(--glass-shadow) / 0.06); }
.gbc [aria-current] { padding: 2px 4px; font-weight: 600; color: var(--glass-fg); }
.gbc-sep { opacity: 0.4; }

/* ---------- Sidebar ---------- */
.gsb.gc { gap: 14px; width: 240px; padding: 12px; border-radius: min(var(--glass-radius), 22px); }
.gsb[data-collapsed] { width: 64px; align-items: center; }
.gsb-nav { display: flex; flex-direction: column; gap: 14px; }
.gsb-sec { display: flex; flex-direction: column; gap: 2px; }
.gsb-label { padding: 0 10px 4px; font-size: 11.5px; font-weight: 600; letter-spacing: 0.02em; text-transform: uppercase; color: rgb(var(--glass-shadow) / 0.5); }
.gsb-item { position: relative; display: flex; align-items: center; gap: 10px; width: 100%; min-height: 36px; padding: 0 10px; border: 0; border-radius: min(18px, max(10px, calc((var(--glass-radius, 12px) - 12px) * 100 + 10px))); background: none; font: inherit; font-size: 14px; color: rgb(var(--glass-shadow) / 0.75); text-align: left; cursor: pointer; transition: background 0.15s, color 0.15s; }
.gsb[data-collapsed] .gsb-item { justify-content: center; width: 40px; padding: 0; }
.gsb-item:hover { background: rgb(var(--glass-shadow) / 0.06); color: var(--glass-fg); }
.gsb-item[aria-current="page"] { color: var(--glass-fg); font-weight: 600; background: rgb(var(--glass-shadow) / 0.08); }
.gsb-item[aria-current="page"]::before { content: ""; position: absolute; left: -12px; top: 9px; bottom: 9px; width: 3px; border-radius: 0 3px 3px 0; background: var(--glass-tint); }
.gsb-item:focus-visible { outline: 2px solid var(--glass-focus, var(--glass-tint)); outline-offset: -2px; }
.gsb-icon { display: inline-flex; flex: none; }
.gsb-icon svg { width: 18px; height: 18px; }
.gsb-text { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.gsb-count { flex: none; min-width: 20px; padding: 1px 7px; border-radius: 999px; font-size: 11.5px; font-weight: 600; text-align: center; color: var(--glass-on-tint); background: var(--glass-tint); }
.gsb-head, .gsb-foot { display: flex; align-items: center; gap: 10px; }
.gsb-foot { margin-top: auto; padding-top: 10px; border-top: 1px solid rgb(var(--glass-shadow) / 0.08); }

/* ---------- Charts ---------- */
.gch { position: relative; width: 100%; color: var(--glass-fg); }
.gch svg { display: block; width: 100%; height: auto; overflow: visible; }
.gch-grid { stroke: rgb(var(--glass-shadow) / 0.08); stroke-width: 1; vector-effect: non-scaling-stroke; }
.gch-axis { font-size: 11px; fill: rgb(var(--glass-shadow) / 0.5); font-family: inherit; }
.gch-line { fill: none; stroke: var(--c); stroke-width: 2.4; stroke-linecap: round; vector-effect: non-scaling-stroke; }
.gch-area { fill: var(--c); opacity: 0.2; -webkit-mask-image: linear-gradient(#000, transparent 92%); mask-image: linear-gradient(#000, transparent 92%); }
.gch-bar { fill: var(--c); opacity: 0.9; transition: opacity 0.15s; }
.gch-bar[data-on] { opacity: 1; filter: brightness(1.08); }
.gch-cursor { stroke: rgb(var(--glass-shadow) / 0.25); stroke-dasharray: 3 3; vector-effect: non-scaling-stroke; }
.gch-dot { fill: var(--c); stroke: var(--gch-bg, #fff); stroke-width: 2; }
:is([data-glass-mode="dark"], .dark) .gch-dot { --gch-bg: #1c1c20; }
.gch [data-series="0"], .gch-legend [data-series="0"], .gdn [data-series="0"] { --c: var(--gch-0); }
.gch [data-series="1"], .gch-legend [data-series="1"], .gdn [data-series="1"] { --c: var(--gch-1); }
.gch [data-series="2"], .gdn [data-series="2"] { --c: var(--gch-2); }
.gch [data-series="3"], .gdn [data-series="3"] { --c: var(--gch-3); }
.gch-tip { position: absolute; top: 4px; transform: translateX(-50%); display: flex; flex-direction: column; gap: 2px; padding: 8px 10px; border-radius: 10px; font-size: 12px; white-space: nowrap; pointer-events: none; color: #fff; background: rgb(28 28 32 / 0.92); box-shadow: 0 8px 20px -8px rgb(0 0 0 / 0.4); }
.gch-tip span, .gch-legend span { display: inline-flex; align-items: center; gap: 6px; }
.gch-tip i, .gch-legend i, .gdn-legend i { width: 8px; height: 8px; border-radius: 2px; background: var(--c); }
.gch-tip b { margin-left: auto; padding-left: 12px; }
.gch-legend { display: flex; gap: 16px; margin-top: 8px; font-size: 12.5px; color: rgb(var(--glass-shadow) / 0.7); }
.gsp-line { fill: none; stroke: var(--sp, var(--gch-0)); stroke-width: 1.8; stroke-linecap: round; }
.gsp-area { fill: var(--sp, var(--gch-0)); opacity: 0.18; -webkit-mask-image: linear-gradient(#000, transparent); mask-image: linear-gradient(#000, transparent); }
.gsp[data-tone="good"] { --sp: var(--gch-good); }
.gsp[data-tone="bad"] { --sp: var(--gch-bad); }
.gdn { display: flex; align-items: center; gap: 22px; flex-wrap: wrap; color: var(--glass-fg); }
.gdn svg { flex: none; transform: rotate(-90deg); }
.gdn svg text { transform: rotate(90deg); transform-origin: 64px 64px; }
.gdn-track { fill: none; stroke: rgb(var(--glass-shadow) / 0.08); stroke-width: 14; }
.gdn-part { fill: none; stroke: var(--c); stroke-width: 14; stroke-linecap: butt; }
.gdn-total { font-size: 20px; font-weight: 600; fill: var(--glass-fg); font-family: inherit; }
.gdn-label { font-size: 10px; fill: rgb(var(--glass-shadow) / 0.55); font-family: inherit; }
.gdn-legend { display: flex; flex-direction: column; gap: 8px; margin: 0; padding: 0; list-style: none; font-size: 13.5px; }
.gdn-legend li { display: flex; align-items: center; gap: 8px; }
.gdn-legend b { margin-left: auto; padding-left: 16px; font-weight: 600; font-variant-numeric: tabular-nums; }

/* ---------- Stat card ---------- */
.gst.gc { gap: 10px; padding: 18px 20px; }
.gst-label { font-size: 13px; font-weight: 500; color: rgb(var(--glass-shadow) / 0.62); }
.gst-row { display: flex; align-items: flex-end; justify-content: space-between; gap: 12px; min-width: 0; }
.gst-row > .gsp { flex: 0 1 96px; min-width: 40px; }
.gst-value { white-space: nowrap; }
.gst-value { font-size: 28px; font-weight: 600; letter-spacing: -0.03em; font-variant-numeric: tabular-nums; line-height: 1.1; }
.gst-foot { display: flex; align-items: center; gap: 8px; font-size: 12.5px; color: rgb(var(--glass-shadow) / 0.55); }
.gst-change { display: inline-flex; align-items: center; gap: 2px; padding: 2px 7px 2px 4px; border-radius: 999px; font-weight: 600; color: var(--gch-bad); background: color-mix(in srgb, var(--gch-bad) 12%, transparent); }
.gst-change[data-good] { color: var(--gch-good); background: color-mix(in srgb, var(--gch-good) 12%, transparent); }

/* ---------- Data table ---------- */
.gdt { display: flex; flex-direction: column; gap: 10px; min-width: 0; color: var(--glass-fg); }
.gdt-bar { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; min-height: 40px; }
.gdt-search { flex: 1; min-width: 180px; max-width: 320px; }
.gdt-tools { display: flex; gap: 8px; margin-left: auto; }
.gdt-bulk { display: flex; align-items: center; gap: 12px; width: 100%; padding: 6px 8px 6px 14px; border-radius: min(var(--glass-radius), 14px); font-size: 14px; background: color-mix(in srgb, var(--glass-tint) 10%, transparent); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--glass-tint) 25%, transparent); animation: gdt-in 0.2s cubic-bezier(0.2, 0.8, 0.2, 1); }
@keyframes gdt-in { from { opacity: 0; transform: translateY(-4px); } }
.gdt-bulk-actions { display: flex; gap: 8px; margin-left: auto; }
.gdt-clear { border: 0; background: none; font: inherit; font-size: 13px; color: rgb(var(--glass-shadow) / 0.65); cursor: pointer; }
.gdt .gtb th, .gdt .gtb td { padding-block: 10px; }
.gdt-cell-check { width: 44px; padding-right: 0 !important; }
.gdt-cell-actions { width: 52px; text-align: right; }
.gdt-check { gap: 0; }
.gdt-check .gck { width: 18px; height: 18px; }
.gdt-check .gck svg { width: 12px; height: 12px; }
.gdt-sort { display: inline-flex; align-items: center; gap: 4px; padding: 0; border: 0; background: none; font: inherit; color: inherit; cursor: pointer; }
.gdt-sort svg { opacity: 0.25; }
.gdt-sort svg[data-on] { opacity: 1; color: var(--glass-fg); }
.gdt tr[data-selected] td { background: color-mix(in srgb, var(--glass-tint) 7%, transparent); }
.gdt-empty { padding: 36px 16px !important; text-align: center; color: rgb(var(--glass-shadow) / 0.6); }
.gdt-foot { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; font-size: 13px; color: rgb(var(--glass-shadow) / 0.6); }
.gpg { display: inline-flex; align-items: center; gap: 4px; }
.gpg-btn { display: grid; place-items: center; min-width: 32px; height: 32px; padding: 0 8px; border: 0; border-radius: min(16px, max(9px, calc((var(--glass-radius, 12px) - 12px) * 100 + 9px))); background: none; font: inherit; font-size: 13px; font-variant-numeric: tabular-nums; color: var(--glass-fg); cursor: pointer; }
.gpg-btn:hover:not(:disabled) { background: rgb(var(--glass-shadow) / 0.07); }
.gpg-btn[aria-current="page"] { font-weight: 600; color: var(--glass-on-tint); background: var(--glass-tint); }
.gpg-btn:disabled { opacity: 0.35; cursor: default; }
.gpg-gap { padding: 0 2px; color: rgb(var(--glass-shadow) / 0.5); }
[data-glass-tint="frost"] .gpg-btn[aria-current="page"] { color: #262d3a; background: linear-gradient(180deg, #f6f8fb, #dfe4ec); box-shadow: inset 0 1px 0 #fff, 0 0 0 0.5px rgb(70 82 104 / 0.25); }

/* ---------- Command menu ---------- */
.gcmd.gdl { width: min(560px, calc(100vw - 32px)); max-height: min(520px, 80vh); margin-top: 12vh; padding: 10px; display: none; flex-direction: column; gap: 8px; }
.gcmd.gdl[open] { display: flex; }
.gcmd-search { --gf-h: 46px; }
.gcmd-esc { flex: none; padding: 2px 6px; border-radius: 6px; font-size: 11px; font-family: inherit; color: rgb(var(--glass-shadow) / 0.6); background: rgb(var(--glass-shadow) / 0.07); }
.gcmd-list { overflow-y: auto; padding: 2px; }
.gcmd-group { padding: 10px 10px 4px; font-size: 11.5px; font-weight: 600; letter-spacing: 0.02em; text-transform: uppercase; color: rgb(var(--glass-shadow) / 0.5); }
.gcmd-item { display: flex; align-items: center; gap: 10px; min-height: 40px; padding: 0 10px; border-radius: min(var(--glass-radius), 10px); font-size: 14px; cursor: pointer; }
.gcmd-item[aria-selected="true"] { background: rgb(var(--glass-shadow) / 0.08); }
.gcmd-icon { display: inline-flex; opacity: 0.7; }
.gcmd-icon svg { width: 17px; height: 17px; }
.gcmd-text { flex: 1; min-width: 0; display: flex; gap: 8px; align-items: baseline; }
.gcmd-hint { font-size: 12.5px; color: rgb(var(--glass-shadow) / 0.5); }
.gcmd-keys { display: inline-flex; gap: 3px; }
.gcmd-keys kbd { min-width: 20px; padding: 1px 6px; border-radius: 5px; font-family: inherit; font-size: 11.5px; text-align: center; color: rgb(var(--glass-shadow) / 0.7); background: rgb(var(--glass-shadow) / 0.07); box-shadow: inset 0 -1px 0 rgb(var(--glass-shadow) / 0.12); }
.gcmd-empty { padding: 26px 10px; margin: 0; text-align: center; font-size: 14px; color: rgb(var(--glass-shadow) / 0.6); }

/* ---------- Drawer ---------- */
.gdr.gdl { position: fixed; inset: 0 0 0 auto; width: min(440px, 100vw); max-width: none; height: 100%; max-height: none; margin: 0; padding: 0; border-radius: 24px 0 0 24px; display: none; flex-direction: column; }
.gdr.gdl[open] { display: flex; animation: gdr-in 0.32s cubic-bezier(0.2, 0.8, 0.2, 1); }
.gdr[data-side="left"].gdl { inset: 0 auto 0 0; border-radius: 0 24px 24px 0; }
.gdr[data-side="left"].gdl[open] { animation-name: gdr-in-left; }
@keyframes gdr-in { from { transform: translateX(40px); opacity: 0; } }
@keyframes gdr-in-left { from { transform: translateX(-40px); opacity: 0; } }
.gdr-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; padding: 22px 22px 14px; border-bottom: 1px solid rgb(var(--glass-shadow) / 0.08); }
.gdr-body { flex: 1; overflow-y: auto; display: flex; flex-direction: column; gap: 16px; padding: 20px 22px; }
.gdr-foot { display: flex; justify-content: flex-end; gap: 10px; padding: 14px 22px; border-top: 1px solid rgb(var(--glass-shadow) / 0.08); }

/* ---------- Toasts ---------- */
.gts-wrap { position: fixed; z-index: 60; display: flex; flex-direction: column; gap: 10px; width: min(380px, calc(100vw - 32px)); pointer-events: none; }
.gts-wrap[data-position="bottom-right"] { right: 20px; bottom: 96px; }
.gts-wrap[data-position="top-right"] { right: 20px; top: 70px; }
.gts-wrap[data-position="bottom-center"] { left: 50%; bottom: 96px; transform: translateX(-50%); }
.gtst.gp { position: relative; top: auto; left: auto; display: flex; align-items: flex-start; gap: 10px; width: 100%; max-width: none; max-height: none; padding: 12px 10px 12px 14px; border-radius: min(var(--glass-radius), 16px); pointer-events: auto; animation: gtst-in 0.36s cubic-bezier(0.34, 1.4, 0.5, 1); transition: opacity 0.2s, transform 0.2s; color: var(--glass-fg); }
.gtst[data-leaving] { opacity: 0; transform: translateX(16px) scale(0.98); }
@keyframes gtst-in { from { opacity: 0; transform: translateY(14px) scale(0.96); } }
.gtst-mark { display: grid; place-items: center; flex: none; width: 22px; height: 22px; margin-top: 1px; border-radius: 50%; color: #fff; background: rgb(var(--glass-shadow) / 0.55); }
.gtst-mark svg { width: 14px; height: 14px; stroke-width: 2.4; }
.gtst[data-tone="success"] .gtst-mark { background: #17a065; }
.gtst[data-tone="danger"] .gtst-mark { background: #d12c3a; }
.gtst-body { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; font-size: 14px; }
.gtst-body span { font-size: 13px; color: rgb(var(--glass-shadow) / 0.65); }
.gtst-action { flex: none; align-self: center; padding: 5px 10px; border: 0; border-radius: 8px; font: inherit; font-size: 13px; font-weight: 600; color: var(--glass-fg); background: rgb(var(--glass-shadow) / 0.08); cursor: pointer; }

/* ---------- Empty state and skeleton ---------- */
.gem { display: flex; flex-direction: column; align-items: center; gap: 8px; padding: 36px 20px; text-align: center; color: var(--glass-fg); }
.gem-icon { display: grid; place-items: center; width: 52px; height: 52px; margin-bottom: 6px; border-radius: 16px; color: var(--glass-fg); background: rgb(var(--glass-shadow) / 0.06); box-shadow: inset 0 0 0 1px rgb(var(--glass-shadow) / 0.08); }
.gem-icon svg { width: 24px; height: 24px; }
.gem-title { margin: 0; font-size: 17px; font-weight: 600; }
.gem-text { max-width: 36ch; margin: 0; font-size: 14px; color: rgb(var(--glass-shadow) / 0.62); }
.gem-actions { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-top: 10px; }
.gsk { display: block; background: linear-gradient(90deg, rgb(var(--glass-shadow) / 0.07) 25%, rgb(var(--glass-shadow) / 0.13) 45%, rgb(var(--glass-shadow) / 0.07) 65%) 0 0 / 300% 100%; animation: gsk 1.4s ease-in-out infinite; }
.gsk-lines { display: flex; flex-direction: column; gap: 8px; width: 100%; }
@keyframes gsk { from { background-position: 100% 0; } to { background-position: 0 0; } }

/* ---------- Date range ---------- */
.gdp { position: relative; }
.gdp-trigger { cursor: pointer; }
.gdp-pop.gp { display: flex; gap: 6px; width: auto; max-width: min(520px, 92vw); max-height: none; padding: 8px; }
.gdp-presets { display: flex; flex-direction: column; gap: 2px; min-width: 120px; padding-right: 6px; border-right: 1px solid rgb(var(--glass-shadow) / 0.08); }
.gdp-preset { padding: 7px 10px; border: 0; border-radius: 8px; background: none; font: inherit; font-size: 13.5px; text-align: left; color: var(--glass-fg); cursor: pointer; }
.gdp-preset:hover { background: rgb(var(--glass-shadow) / 0.07); }
.gdp-cal { padding: 2px 4px; color: var(--glass-fg); }
.gdp-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 6px; font-size: 14px; }
.gdp-grid { display: grid; grid-template-columns: repeat(7, 34px); gap: 2px 0; }
.gdp-dow { display: grid; place-items: center; height: 26px; font-size: 11.5px; color: rgb(var(--glass-shadow) / 0.5); }
.gdp-day { height: 34px; border: 0; border-radius: 9px; background: none; font: inherit; font-size: 13px; font-variant-numeric: tabular-nums; color: var(--glass-fg); cursor: pointer; }
.gdp-day:hover { background: rgb(var(--glass-shadow) / 0.08); }
.gdp-day[data-in] { border-radius: 0; background: color-mix(in srgb, var(--glass-tint) 14%, transparent); }
.gdp-day[data-edge] { font-weight: 600; color: var(--glass-on-tint); background: var(--glass-tint); }
.gdp-day[data-today]:not([data-edge]) { box-shadow: inset 0 0 0 1px rgb(var(--glass-shadow) / 0.3); }
.gdp-hint { margin: 8px 2px 2px; font-size: 12px; color: rgb(var(--glass-shadow) / 0.55); }
[data-glass-tint="frost"] .gdp-day[data-edge] { color: #262d3a; background: linear-gradient(180deg, #f6f8fb, #d9dfe8); box-shadow: inset 0 1px 0 #fff, 0 0 0 0.5px rgb(70 82 104 / 0.3); }
@media (max-width: 520px) { .gdp-pop.gp { flex-direction: column; } .gdp-presets { flex-direction: row; flex-wrap: wrap; border-right: 0; padding: 0 0 6px; border-bottom: 1px solid rgb(var(--glass-shadow) / 0.08); } }

/* ---------- Stepper ---------- */
.gstp { position: relative; display: flex; gap: 8px; margin: 0; padding: 0; list-style: none; color: var(--glass-fg); }
.gstp[data-orientation="horizontal"] .gstp-step { display: flex; align-items: flex-start; gap: 10px; flex: 1; min-width: 0; }
.gstp[data-orientation="horizontal"] .gstp-step:last-child { flex: none; }
.gstp[data-orientation="horizontal"] .gstp-step:not(:last-child)::after { content: ""; flex: 1; min-width: 12px; height: 2px; margin-top: 14px; border-radius: 2px; background: rgb(var(--glass-shadow) / 0.12); transition: background 0.3s; }
.gstp[data-orientation="horizontal"] .gstp-step[data-state="done"]::after { background: var(--glass-tint); }
.gstp[data-orientation="horizontal"] .gstp-text { white-space: nowrap; }
.gstp[data-orientation="vertical"] { flex-direction: column; gap: 4px; }
.gstp[data-orientation="vertical"] .gstp-step { position: relative; padding-bottom: 14px; }
.gstp[data-orientation="vertical"] .gstp-step:not(:last-child)::after { content: ""; position: absolute; left: 14px; top: 34px; bottom: 2px; width: 2px; border-radius: 2px; background: rgb(var(--glass-shadow) / 0.12); }
.gstp[data-orientation="vertical"] .gstp-step[data-state="done"]::after { background: var(--glass-tint); }
.gstp-btn { display: flex; align-items: flex-start; gap: 10px; padding: 0; border: 0; background: none; font: inherit; color: inherit; text-align: left; }
button.gstp-btn { cursor: pointer; }
.gstp-mark { display: grid; place-items: center; flex: none; width: 30px; height: 30px; border-radius: 50%; font-size: 13px; font-weight: 600; color: rgb(var(--glass-shadow) / 0.6); background: var(--gstp-bg, #fff); box-shadow: inset 0 0 0 1.5px rgb(var(--glass-shadow) / 0.2); transition: background 0.25s, color 0.25s, box-shadow 0.25s; }
.gstp-step[data-state="current"] .gstp-mark { color: var(--glass-fg); box-shadow: inset 0 0 0 2px var(--glass-tint), 0 0 0 4px color-mix(in srgb, var(--glass-tint) 18%, transparent); }
.gstp-step[data-state="done"] .gstp-mark { color: var(--glass-on-tint); background: var(--glass-tint); box-shadow: none; }
.gstp-text { display: flex; flex-direction: column; gap: 1px; padding-top: 5px; font-size: 14px; font-weight: 500; }
.gstp-step[data-state="todo"] .gstp-text { color: rgb(var(--glass-shadow) / 0.55); }
.gstp-hint { font-size: 12.5px; font-weight: 400; color: rgb(var(--glass-shadow) / 0.55); }
:is([data-glass-mode="dark"], .dark) .gstp-mark { --gstp-bg: #1c1c20; }
[data-glass-tint="frost"] .gstp-step[data-state="done"] .gstp-mark { color: #262d3a; background: linear-gradient(180deg, #f6f8fb, #d9dfe8); box-shadow: inset 0 1px 0 #fff, 0 0 0 0.5px rgb(70 82 104 / 0.3); }
/* When the row is too narrow for every label, only the current step keeps its name */
.gstp[data-orientation="horizontal"] { container-type: inline-size; width: 100%; }
@container (max-width: 560px) { .gstp-text { display: none; } .gstp-step[data-state="current"] .gstp-text { display: flex; } .gstp-step[data-state="current"] { flex: none; } }

@media (prefers-reduced-motion: reduce) {
  .gsk, .gtst, .gdr.gdl[open], .gdt-bulk { animation: none; }
}

/* Stepper on a dark picture */
[data-glass-on="dark"] .gstp { color: #fff; }
[data-glass-on="dark"] .gstp-mark { --gstp-bg: rgb(255 255 255 / 0.14); color: #fff; box-shadow: inset 0 0 0 1.5px rgb(255 255 255 / 0.45); -webkit-backdrop-filter: blur(10px); backdrop-filter: blur(10px); }
[data-glass-on="dark"] .gstp-step[data-state="current"] .gstp-mark { color: #fff; box-shadow: inset 0 0 0 2px #fff, 0 0 0 4px rgb(255 255 255 / 0.2); }
[data-glass-on="dark"] .gstp-step[data-state="done"] .gstp-mark { color: var(--glass-on-tint); background: var(--glass-tint); box-shadow: none; }
[data-glass-on="dark"] .gstp-step[data-state="todo"] .gstp-text, [data-glass-on="dark"] .gstp-hint { color: rgb(255 255 255 / 0.72); }
[data-glass-on="dark"] .gstp-step:not(:last-child)::after { background: rgb(255 255 255 / 0.3); }
[data-glass-on="dark"] [data-glass-tint="frost"] .gstp-step[data-state="done"] .gstp-mark, [data-glass-tint="frost"] [data-glass-on="dark"] .gstp-step[data-state="done"] .gstp-mark { color: #262d3a; background: linear-gradient(180deg, #f6f8fb, #d9dfe8); }
[data-glass-on="dark"] .gdp-day[data-in], :is([data-glass-mode="dark"], .dark) .gdp-day[data-in] { background: rgb(255 255 255 / 0.12); }
:is([data-glass-mode="dark"], .dark) [data-glass-tint="frost"] :is(.gch, .gdn, .gsp, .gst), :is([data-glass-mode="dark"], .dark)[data-glass-tint="frost"] :is(.gch, .gdn) { --gch-0: #d3d9e3; --gch-1: #8b95a5; --gch-2: #586273; --gch-3: #f1f3f6; }
